<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';require_method('GET');$u=current_user();$id=trim((string)($_GET['id']??''));$s=db()->prepare("SELECT failed_report_path,original_filename FROM import_jobs WHERE tenant_id=? AND public_id=? AND status='COMPLETED'");$s->execute([$u['tenant_id'],$id]);$r=$s->fetch();if(!$r||!$r['failed_report_path']||!is_file($r['failed_report_path']))throw new ApiError(404,'Failed-row report not found.');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.preg_replace('/[^a-zA-Z0-9._-]/','_',pathinfo($r['original_filename'],PATHINFO_FILENAME)).'-failed.csv"');header('Content-Length: '.filesize($r['failed_report_path']));readfile($r['failed_report_path']);exit;
